-- ------------------------------------------------------------------ rotation pick
-- Does this client have specializations that pick the rotation? (MoP yes;
-- Era/TBC/Forever no: their imported rotations are kept per class, spec 0.)
function Sim.UsesSpecs()
	return ns.GAME == "mists"
end

-- WoWSims rotations for the current class/spec, plus any imported in game
-- (SimImport.lua). Returns list (or nil), class token, spec index.
function Sim.Rotations()
	local token = ns.ClassToken and ns.ClassToken()
	local spec = Sim.Spec()
	if not Sim.UsesSpecs() then
		spec = 0
	end
	if not token or (spec == 0 and Sim.UsesSpecs()) then
		return nil, token, spec
	end
	local data = ns.SimData
	local base = data and data.specs and data.specs[token] and data.specs[token][spec]
	local imported = Sim.Imported and Sim.Imported(token, spec) or {}
	local workshop = Sim.Workshop and Sim.Workshop(token, spec) or {}
	if #imported == 0 and #workshop == 0 then
		return base, token, spec
	end
	local list = {}
	for _, rot in ipairs(base or {}) do
		list[#list + 1] = rot
	end
	for _, rot in ipairs(workshop) do
		list[#list + 1] = rot
	end
	for _, rot in ipairs(imported) do
		list[#list + 1] = rot
	end
	return list, token, spec
end

-- ------------------------------------------------------------ Auto (Forever)
-- WoW Forever bundles the WoWSims Forever rotations (SimData_Forever.lua), each
-- tagged with its role and the talent points of the build it was made for,
-- plus a starter rotation for levels 1-19. "Auto" (the default) picks the
-- starter below level 20, then the rotation for your playstyle whose talents
-- are closest to yours.
Sim.AUTO = "auto"
Sim.STARTER_LEVEL = 20

local talentCache, talentAt = nil, -999
-- Points spent in each talent tree, e.g. {0, 11, 40}.
function Sim.TalentPoints()
	local t = now()
	if talentCache and t - talentAt < 5 then
		return talentCache
	end
	local pts = { 0, 0, 0 }
	local n = num(call(GetNumTalentTabs), 0)
	for i = 1, math.min(n, 3) do
		local r = { call(GetTalentTabInfo, i) }
		-- Classic: name, icon, pointsSpent; later clients: id, name, desc, icon, pointsSpent
		local spent = r[3]
		if type(spent) ~= "number" or not readable(spent) then
			spent = r[5]
		end
		pts[i] = (type(spent) == "number" and readable(spent)) and spent or 0
	end
	talentCache, talentAt = pts, t
	return pts
end

function Sim.InvalidateTalents()
	talentCache = nil
end

-- the rotation role your playstyle needs, or nil (healing: no WoWSims rotation)
local function wantedRole(token)
	local role = ns.db and ns.db.role or "damage"
	if role == "heal" then
		return nil
	end
	if role == "tank" then
		return "tank"
	end
	if token == "HUNTER" then
		return role == "melee" and "melee" or "range"
	end
	if token == "SHAMAN" then
		return role == "melee" and "melee" or "caster"
	end
	return "damage"
end

local function similarity(a, b)
	local dot, na, nb = 0, 0, 0
	for i = 1, 3 do
		local x, y = a[i] or 0, b[i] or 0
		dot, na, nb = dot + x * y, na + x * x, nb + y * y
	end
	if na == 0 or nb == 0 then
		return 0
	end
	return dot / math.sqrt(na * nb)
end

-- The rotation Auto uses right now (nil: use the built-in list).
function Sim.AutoPick(list, token)
	-- a rotation you made in the Workshop app comes before the bundled ones
	for _, rot in ipairs(list or {}) do
		if rot.workshop then
			return rot
		end
	end
	local starter, cands = nil, {}
	local want = wantedRole(token)
	for _, rot in ipairs(list or {}) do
		if rot.starter then
			starter = starter or rot
		elseif rot.role and not rot.imported and not rot.workshop and rot.role == want then
			cands[#cands + 1] = rot
		end
	end
	if not want then
		return nil
	end
	local level = num(call(UnitLevel, "player"), 60)
	if starter and level < Sim.STARTER_LEVEL then
		return starter
	end
	if #cands == 0 then
		return starter
	end
	if #cands == 1 then
		return cands[1]
	end
	-- a Paladin playstyle that names a build (Seal Twist, Shockadin)
	local style = ns.db and ns.db.role
	for _, rot in ipairs(cands) do
		if rot.style and rot.style == style then
			return rot
		end
	end
	local mine = Sim.TalentPoints()
	local best, bestScore = cands[1], -1
	for _, rot in ipairs(cands) do
		local score = rot.talents and similarity(mine, rot.talents) or 0
		if score > bestScore + 1e-9 then
			best, bestScore = rot, score
		end
	end
	return best
end

-- True when Auto is choosing (Forever, nothing picked, or Auto picked).
function Sim.IsAuto(token, spec)
	if ns.GAME ~= "forever" then
		return false
	end
	local pick = ns.db and ns.db.simPick and ns.db.simPick[(token or "") .. ":" .. (spec or 0)]
	return pick == nil or pick == Sim.AUTO
end

function Sim.Current()
	local list, token, spec = Sim.Rotations()
	if not list or #list == 0 then
		return nil
	end
	local pick = ns.db and ns.db.simPick and ns.db.simPick[token .. ":" .. spec]
	if ns.GAME == "forever" and (pick == nil or pick == Sim.AUTO) then
		local rot = Sim.AutoPick(list, token)
		-- say so when Auto moves on (level 20, a respec, a new playstyle)
		local file = rot and rot.file or "builtin"
		if Sim.lastAuto and Sim.lastAuto ~= file and ns.Print then
			ns.Print(ns.T("SIM_AUTO_SWITCH"):format(rot and rot.name or ns.T("SIM_PICK_AUTO_BUILTIN")))
		end
		Sim.lastAuto = file
		return rot
	end
	if pick then
		for _, rot in ipairs(list) do
			if rot.file == pick then
				return rot
			end
		end
	end
	return list[1]
end

function Sim.Active()
	return Sim.Current() ~= nil
end

-- /rcr apl: switch to the next WoWSims rotation for this spec.
function Sim.Cycle()
	local list, token, spec = Sim.Rotations()
	if not list or #list == 0 then
		return nil
	end
	ns.db.simPick = ns.db.simPick or {}
	local key = token .. ":" .. spec
	if ns.GAME == "forever" then
		-- Auto, then each rotation, then back to Auto
		local pick = ns.db.simPick[key]
		if pick == nil or pick == Sim.AUTO then
			ns.db.simPick[key] = list[1].file
			return list[1], #list + 1
		end
		for i, rot in ipairs(list) do
			if rot.file == pick then
				if i == #list then
					ns.db.simPick[key] = Sim.AUTO
					return Sim.Current(), #list + 1, true
				end
				ns.db.simPick[key] = list[i + 1].file
				return list[i + 1], #list + 1
			end
		end
		ns.db.simPick[key] = Sim.AUTO
		return Sim.Current(), #list + 1, true
	end
	local cur = Sim.Current() or list[1]
	local idx = 1
	for i, rot in ipairs(list) do
		if rot == cur then
			idx = i
		end
	end
	local nextRot = list[(idx % #list) + 1]
	ns.db.simPick[key] = nextRot.file
	return nextRot, #list
end

-- ------------------------------------------------------------------ never suggest
-- Spells WoWSims uses for simulation value but a player saves for the right
-- moment: personal defensives and raid-wide cooldowns. Applied on top of every
-- rotation (bundled or imported), so WoWSims updates never bring them back.
-- Players can add or remove spells per character (HUD right-click, /rcr block).
Sim.DEFAULT_BLOCK = {
	[48707] = "Anti-Magic Shell",
	[48792] = "Icebound Fortitude",
	[51052] = "Anti-Magic Zone",
	[42650] = "Army of the Dead",
	[61999] = "Raise Ally",
	[2825] = "Bloodlust",
	[32182] = "Heroism",
	[80353] = "Time Warp",
	[90355] = "Ancient Hysteria",
	[120668] = "Stormlash Totem",
	[114207] = "Skull Banner",
	[20484] = "Rebirth",
}

-- Spec blocks from the tuning file (set per queue build; see Sim.BuildQueue).
local tuningBlock = {}

local function blockState(id)
	if not id then
		return nil
	end
	local user = ns.db and ns.db.simBlock
	if user and user[id] ~= nil then
		return user[id]
	end
	if Sim.DEFAULT_BLOCK[id] or tuningBlock[id] then
		return true
	end
	return nil
end

-- Blocked by ID (as written in the rotation or as resolved) or by name.
function Sim.IsBlocked(id, rid)
	local state = blockState(id)
	if state == nil and rid and rid ~= id then
		state = blockState(rid)
	end
	if state ~= nil then
		return state
	end
	local names = ns.db and ns.db.simBlockNames
	local name = spellName(rid or id)
	if names and name then
		for bid, bname in pairs(names) do
			if bname == name then
				local s = blockState(bid)
				if s ~= nil then
					return s
				end
			end
		end
	end
	return false
end

function Sim.SetBlocked(id, blocked)
	ns.db.simBlock = ns.db.simBlock or {}
	ns.db.simBlockNames = ns.db.simBlockNames or {}
	ns.db.simBlock[id] = blocked and true or false
	ns.db.simBlockNames[id] = spellName(id) or Sim.DEFAULT_BLOCK[id]
	if ns.InvalidateTick then
		ns.InvalidateTick()
	end
end

-- HUD right-click: stop suggesting this spell.
function Sim.ToggleBlock(id)
	local now = not Sim.IsBlocked(id)
	Sim.SetBlocked(id, now)
	if ns.Print then
		local name = spellName(id) or tostring(id)
		ns.Print(ns.T(now and "SIM_BLOCKED" or "SIM_UNBLOCKED"):format(name))
	end
	return now
end

-- Everything currently blocked: { {id=, name=, default=bool}, ... } sorted by name.
function Sim.BlockedList()
	local out, seen = {}, {}
	local function add(id)
		if not seen[id] and blockState(id) then
			seen[id] = true
			out[#out + 1] = { id = id, name = (ns.db.simBlockNames and ns.db.simBlockNames[id]) or spellName(id) or Sim.DEFAULT_BLOCK[id] or tostring(id),
				default = Sim.DEFAULT_BLOCK[id] ~= nil }
		end
	end
	for id in pairs(Sim.DEFAULT_BLOCK) do
		add(id)
	end
	for id in pairs(ns.db and ns.db.simBlock or {}) do
		add(id)
	end
	table.sort(out, function(a, b)
		return tostring(a.name) < tostring(b.name)
	end)
	return out
end

function Sim.ResetBlocks()
	ns.db.simBlock = nil
	ns.db.simBlockNames = nil
	if ns.InvalidateTick then
		ns.InvalidateTick()
	end
end

-- Resolve "/rcr block <name or id>" text to a spell ID.
function Sim.FindSpell(text)
	text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
	local id = tonumber(text)
	if id then
		return id
	end
	if text == "" then
		return nil
	end
	for bid, bname in pairs(ns.db and ns.db.simBlockNames or {}) do
		if type(bname) == "string" and bname:lower() == text:lower() then
			return bid
		end
	end
	for bid, bname in pairs(Sim.DEFAULT_BLOCK) do
		if bname:lower() == text:lower() then
			return bid
		end
	end
	local info = C_Spell and C_Spell.GetSpellInfo and call(C_Spell.GetSpellInfo, text)
	if type(info) == "table" and info.spellID then
		return info.spellID
	end
	local _, _, _, _, _, _, sid = call(GetSpellInfo, text)
	return sid
end

-- ------------------------------------------------------------------ tuning
-- Per-spec fixes from rotations/tuning/*.json, compiled into
-- ns.SimData.tuning by the converter. Applied to every rotation for the spec,
-- bundled or imported: require (extra condition), move, add, block.
local tunedCache = setmetatable({}, { __mode = "k" })

function Sim.TuningFor(rot, token, spec)
	local all = ns.SimData and ns.SimData.tuning
	if not all then
		return nil
	end
	local merged
	local keys = { "*", (token or "?") .. ":" .. tostring(spec or 0), rot and rot.file and ("file:" .. rot.file) or nil }
	for i = 1, 3 do
		local rules = keys[i] and all[keys[i]]
		if rules then
			merged = merged or { block = {}, require = {}, move = {}, add = {} }
			for kind, list in pairs(rules) do
				if merged[kind] then
					for _, r in ipairs(list) do
						merged[kind][#merged[kind] + 1] = r
					end
				end
			end
		end
	end
	return merged
end

local function indexOf(list, id)
	for i, item in ipairs(list) do
		if item.id == id then
			return i
		end
	end
	return nil
end

-- The rotation's list with the tuning applied (cached per rotation).
function Sim.ListFor(rot, token, spec)
	local rules = Sim.TuningFor(rot, token, spec)
	if not rules then
		return rot.list, nil
	end
	local cached = tunedCache[rot]
	if cached and cached.key == (token or "?") .. ":" .. tostring(spec) then
		return cached.list, rules
	end
	local need = {}
	for _, r in ipairs(rules.require) do
		need[r.id] = need[r.id] and { k = "and", v = { need[r.id], r.c } } or r.c
	end
	local list = {}
	for _, item in ipairs(rot.list) do
		if item.id and need[item.id] and not item.cancel then
			local copy = {}
			for k, v in pairs(item) do
				copy[k] = v
			end
			copy.c = item.c and { k = "and", v = { item.c, need[item.id] } } or need[item.id]
			list[#list + 1] = copy
		else
			list[#list + 1] = item
		end
	end
	for _, m in ipairs(rules.move) do
		local from = indexOf(list, m.id)
		if from then
			local item = table.remove(list, from)
			if m.before then
				local at = indexOf(list, m.before)
				table.insert(list, at or (#list + 1), item)
			elseif m.to == "top" then
				table.insert(list, 1, item)
			else
				list[#list + 1] = item
			end
		end
	end
	for _, a in ipairs(rules.add) do
		local item = { id = a.id, c = a.c }
		if need[a.id] then
			item.c = item.c and { k = "and", v = { item.c, need[a.id] } } or need[a.id]
		end
		if a.before then
			table.insert(list, indexOf(list, a.before) or (#list + 1), item)
		elseif a.at == "top" then
			table.insert(list, 1, item)
		else
			list[#list + 1] = item
		end
	end
	tunedCache[rot] = { key = (token or "?") .. ":" .. tostring(spec), list = list }
	return list, rules
end

-- ------------------------------------------------------------------ queue
function Sim.BeginPass()
	pass = { now = GetTime() }
end

-- Spells on the stance bar (seals, presences, stances, forms): the spell ID of
-- each slot, and which one is active. Seals and presences live there rather
-- than on action bars, so "only suggest spells on my bars" lets them through.
local function stanceSlots()
	if pass.stances then
		return pass.stances
	end
	local list = { active = nil, ids = {} }
	local n = num(call(GetNumShapeshiftForms), 0)
	for i = 1, n do
		local _, active, _, sid = call(GetShapeshiftFormInfo, i)
		sid = num(sid, 0)
		if sid > 0 then
			list.ids[sid] = true
			if active then
				list.active = sid
			end
		end
	end
	list.index = num(call(GetShapeshiftForm), 0)
	pass.stances = list
	return list
end
Sim.StanceSlots = stanceSlots

local function onBar(id)
	if ns.db and ns.db.barOnly == false then
		return true
	end
	if stanceSlots().ids[id] then
		return true
	end
	if ns.SpellOnBar then
		return ns.SpellOnBar(id)
	end
	return true
end

local function test(c)
	if c == nil then
		return true
	end
	local ok, res = pcall(ev, c)
	if not ok then
		Sim.lastError = res
		return false
	end
	return truthy(res)
end
Sim.Test = test

-- First three castable spells whose conditions pass, in priority order.
function Sim.BuildQueue(rot)
	rot = rot or Sim.Current()
	if not rot then
		return nil
	end
	Sim.BeginPass()
	local _, token, spec = Sim.Rotations()
	local list, rules = Sim.ListFor(rot, token, spec)
	tuningBlock = {}
	if rules then
		for _, id in ipairs(rules.block) do
			tuningBlock[id] = true
		end
	end
	local q, seen = {}, {}
	-- WoW Forever Paladins: WoWSims puts the first seal up before the pull, so its
	-- rotations never ask for one. With no seal up at all, suggest the first seal
	-- the rotation uses.
	if ns.GAME == "forever" and token == "PALADIN" and API.SealUp then
		local okSeal, errSeal = pcall(function()
		local anyUp, first = false, nil
		for _, item in ipairs(list) do
			-- the first seal the rotation uses that you have (Seal of Command
			-- is a talent: at level 20 it's Righteousness)
			if not first and item.id and API.SealUp(item.id) ~= nil and resolve(item.id) then
				first = item.id
			end
		end
		if first then
			local P = ns.Spell and ns.Spell.Paladin or {}
			for _, key in ipairs({ "SealCommand", "SealRighteousness", "SealFury", "SealJustice", "SealLight", "SealWisdom", "SealCrusader" }) do
				if P[key] and V.auraIsActive({ id = P[key], unit = "player" }) then
					anyUp = true
					break
				end
			end
			if not anyUp then
				local rid = resolve(first)
				if rid and canCast(rid) and not Sim.IsBlocked(first, rid) then
					q[1] = rid
					seen[rid] = true
				end
			end
		end
		end)
		if not okSeal then
			Sim.NoteError(errSeal, 0, { id = "seal" })
		end
	end
	-- One line that errors (an API Forever answers oddly) must not empty the
	-- whole queue: it's skipped, and /rcr why shows the error.
	local stop = false
	local function evalItem(item)
		if item.hold then
			if test(item.c) and #q == 0 then
				stop = true
			end
		elseif item.cancel then
			-- "Cancel" lines (end Metamorphosis): only while its aura is up;
			-- press the same button again. Shown with a CANCEL label.
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and V.auraIsActive({ id = item.id, unit = "player" }) and test(item.c) then
				q[#q + 1] = rid
				seen[rid] = true
				q.cancel = q.cancel or {}
				q.cancel[rid] = true
			end
		elseif item.id then
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and canCast(rid) and onBar(rid) and test(item.c) then
				q[#q + 1] = rid
				seen[rid] = true
			end
		end
	end
	for i, item in ipairs(list) do
		if #q >= 3 or stop then
			break
		end
		local ok, err = pcall(evalItem, item)
		if not ok then
			Sim.NoteError(err, i, item)
		end
	end
	if #q < 3 and not (ns.db and ns.db.simLookahead == false) then
		local ok, err = pcall(Sim.FillComingUp, list, q, seen)
		if not ok then
			Sim.NoteError(err)
		end
	end
	return q
end

-- /rcr why: each rotation line and what stopped it
function Sim.Explain(rot)
	rot = rot or Sim.Current()
	if not rot then
		return {}
	end
	Sim.BeginPass()
	local _, token, spec = Sim.Rotations()
	local list = Sim.ListFor(rot, token, spec)
	local out = {}
	for i, item in ipairs(list or {}) do
		if i > 14 then
			break
		end
		local ok, line = pcall(function()
			if item.hold then
				return ("%d. wait-line: %s"):format(i, test(item.c) and "WAITING" or "no")
			end
			local rid = item.id and resolve(item.id)
			local name = API.SpellName and API.SpellName(rid or item.id) or "?"
			if not rid then
				return ("%d. %s (%s): not known"):format(i, tostring(name), tostring(item.id))
			end
			local bits = {}
			bits[#bits + 1] = canCast(rid) and "castable" or "NOT castable"
			bits[#bits + 1] = ("cd %.1f"):format(cooldownRemain(rid))
			bits[#bits + 1] = onBar(rid) and "on bar" or "NOT ON BAR"
			bits[#bits + 1] = test(item.c) and "condition ok" or "condition no"
			return ("%d. %s (%s): %s"):format(i, tostring(name), tostring(rid), table.concat(bits, ", "))
		end)
		out[#out + 1] = ok and line or ("%d. error: %s"):format(i, tostring(line))
	end
	local seal, at = API.CurrentSeal and API.CurrentSeal()
	out[#out + 1] = ("seal tracked: %s%s"):format(tostring(seal or "none"), at and seal and (" (%.0fs ago)"):format(GetTime() - at) or "")
	return out
end

-- the last few rotation errors, for /rcr why
Sim.errors = {}
function Sim.NoteError(err, line, item)
	local text = tostring(err)
	if line then
		text = ("line %d (%s): %s"):format(line, tostring(item and (item.id or (item.hold and "wait"))), text)
	end
	for _, e in ipairs(Sim.errors) do
		if e == text then
			return
		end
	end
	table.insert(Sim.errors, 1, text)
	Sim.errors[6] = nil
end

-- "Coming up": when fewer than three spells are castable right now, fill the
-- rest with rotation spells that come off cooldown within LOOKAHEAD seconds,
-- soonest first, so the HUD shows what to press next instead of going blank
-- (WoWSims rotations "wait" for a cooldown rather than naming the next spell).
-- They pass the same checks as a normal suggestion apart from the cooldown,
-- and are marked in q.soon so they don't flash until they're ready.
Sim.LOOKAHEAD = 6
function Sim.FillComingUp(list, q, seen)
	local soon = {}
	for _, item in ipairs(list) do
		if item.id and not item.hold then
			local rid = resolve(item.id)
			if rid and not seen[rid] and not Sim.IsBlocked(item.id, rid) and onBar(rid) then
				local cd = cooldownRemain(rid)
				local usable = ns.GAME == "forever" or usableNow(rid) ~= false
				if cd > 0 and cd <= Sim.LOOKAHEAD and usable and test(item.c) then
					soon[#soon + 1] = { rid = rid, cd = cd, order = #soon }
					seen[rid] = true
				end
			end
		end
	end
	table.sort(soon, function(a, b)
		if a.cd ~= b.cd then
			return a.cd < b.cd
		end
		return a.order < b.order
	end)
	for _, s in ipairs(soon) do
		if #q >= 3 then
			break
		end
		q[#q + 1] = s.rid
		q.soon = q.soon or {}
		q.soon[s.rid] = true
	end
end

-- ------------------------------------------------------------------ events
local frame = CreateFrame("Frame")
frame:RegisterEvent("PLAYER_REGEN_DISABLED")
frame:RegisterEvent("PLAYER_REGEN_ENABLED")
frame:SetScript("OnEvent", function(_, event)
	if event == "PLAYER_REGEN_DISABLED" then
		combatStart = GetTime()
	else
		combatStart = 0
	end
end)
